module TrigLut(
  input         clock,
                reset,
  input  [15:0] io_in,
  input         io_start,
  output [15:0] io_sin,
                io_cos,
  output        io_busy,
                io_done,
                io_sinEvenSram_enable,
  output [6:0]  io_sinEvenSram_addr,
  input  [15:0] io_sinEvenSram_dataOut,
  output [15:0] io_sinEvenSram_bweb,
  output        io_sinOddSram_enable,
  output [6:0]  io_sinOddSram_addr,
  input  [15:0] io_sinOddSram_dataOut,
  output [15:0] io_sinOddSram_bweb,
  output        io_cosEvenSram_enable,
  output [6:0]  io_cosEvenSram_addr,
  input  [15:0] io_cosEvenSram_dataOut,
  output [15:0] io_cosEvenSram_bweb,
  output        io_cosOddSram_enable,
  output [6:0]  io_cosOddSram_addr,
  input  [15:0] io_cosOddSram_dataOut,
  output [15:0] io_cosOddSram_bweb
);

  reg  [1:0]  stateReg;
  reg         inputNegativeReg;
  reg  [15:0] reducedAbsFp16Reg;
  reg         reqSinNegateReg;
  reg         reqCosNegateReg;
  reg         reqSinBankSelReg;
  reg         reqCosBankSelReg;
  reg  [6:0]  reqSinRowAddrReg;
  reg  [6:0]  reqCosRowAddrReg;
  reg  [15:0] sinReg;
  reg  [15:0] cosReg;
  reg         doneReg;
  wire        _GEN = stateReg == 2'h2;
  wire        _GEN_0 = _GEN & ~reqSinBankSelReg;
  wire        _GEN_1 = _GEN & ~reqCosBankSelReg;
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      stateReg <= 2'h0;
      inputNegativeReg <= 1'h0;
      reducedAbsFp16Reg <= 16'h0;
      reqSinNegateReg <= 1'h0;
      reqCosNegateReg <= 1'h0;
      reqSinBankSelReg <= 1'h0;
      reqCosBankSelReg <= 1'h0;
      reqSinRowAddrReg <= 7'h0;
      reqCosRowAddrReg <= 7'h0;
      sinReg <= 16'h0;
      cosReg <= 16'h0;
      doneReg <= 1'h0;
    end
    else begin
      automatic logic [13:0]     _GEN_2;
      automatic logic            _GEN_3;
      automatic logic            _GEN_4;
      automatic logic            _GEN_5;
      automatic logic            _GEN_6;
      automatic logic [3:0][1:0] _GEN_7;
      _GEN_2 = {|(reducedAbsFp16Reg[14:10]), reducedAbsFp16Reg[9:0], 3'h0};
      _GEN_3 = stateReg == 2'h0;
      _GEN_4 = stateReg == 2'h1;
      _GEN_5 = reducedAbsFp16Reg[14:10] != 5'h1F & reducedAbsFp16Reg[14:0] > 15'h4648;
      _GEN_6 = _GEN_3 | _GEN_4 | _GEN;
      _GEN_7 = {{2'h0}, {2'h3}, {_GEN_5 ? stateReg : 2'h2}, {io_start ? 2'h1 : stateReg}};
      stateReg <= _GEN_7[stateReg];
      if (_GEN_3 & io_start)
        inputNegativeReg <= io_in[15] & (|(io_in[14:0]));
      if (_GEN_3) begin
        if (io_start)
          reducedAbsFp16Reg <= io_in & 16'h7FFF;
      end
      else if (~(_GEN_4 & _GEN_5) | (&(reducedAbsFp16Reg[14:10]))
               & reducedAbsFp16Reg[9:0] == 10'h0) begin
      end
      else if ((&(reducedAbsFp16Reg[14:10])) | ~(|(reducedAbsFp16Reg[14:10]))
               & ~(|(reducedAbsFp16Reg[9:0])) | reducedAbsFp16Reg[14:0] < 15'h4649)
        reducedAbsFp16Reg <= 16'h0;
      else begin
        automatic logic [4:0]  reducedAbsFp16Reg_lhsExpEff;
        automatic logic [4:0]  _reducedAbsFp16Reg_rhsAligned_T;
        automatic logic [13:0] _reducedAbsFp16Reg_rawDiff_T;
        automatic logic        reducedAbsFp16Reg_needShift;
        automatic logic [13:0] reducedAbsFp16Reg_nextExt;
        automatic logic [4:0]  reducedAbsFp16Reg_nextExp;
        automatic logic        reducedAbsFp16Reg_needShift_1;
        automatic logic [13:0] reducedAbsFp16Reg_nextExt_1;
        automatic logic [4:0]  reducedAbsFp16Reg_nextExp_1;
        automatic logic        reducedAbsFp16Reg_needShift_2;
        automatic logic [13:0] reducedAbsFp16Reg_nextExt_2;
        automatic logic [4:0]  reducedAbsFp16Reg_nextExp_2;
        automatic logic        reducedAbsFp16Reg_needShift_3;
        automatic logic [13:0] reducedAbsFp16Reg_nextExt_3;
        automatic logic [4:0]  reducedAbsFp16Reg_nextExp_3;
        automatic logic        reducedAbsFp16Reg_needShift_4;
        automatic logic [13:0] reducedAbsFp16Reg_nextExt_4;
        automatic logic [4:0]  reducedAbsFp16Reg_nextExp_4;
        automatic logic        reducedAbsFp16Reg_needShift_5;
        automatic logic [13:0] reducedAbsFp16Reg_nextExt_5;
        automatic logic [4:0]  reducedAbsFp16Reg_nextExp_5;
        automatic logic        reducedAbsFp16Reg_needShift_6;
        automatic logic [13:0] reducedAbsFp16Reg_nextExt_6;
        automatic logic [4:0]  reducedAbsFp16Reg_nextExp_6;
        automatic logic        reducedAbsFp16Reg_needShift_7;
        automatic logic [13:0] reducedAbsFp16Reg_nextExt_7;
        automatic logic [4:0]  reducedAbsFp16Reg_nextExp_7;
        automatic logic        reducedAbsFp16Reg_needShift_8;
        automatic logic [13:0] reducedAbsFp16Reg_nextExt_8;
        automatic logic [4:0]  reducedAbsFp16Reg_nextExp_8;
        automatic logic        reducedAbsFp16Reg_needShift_9;
        automatic logic [13:0] reducedAbsFp16Reg_nextExt_9;
        automatic logic [4:0]  reducedAbsFp16Reg_nextExp_9;
        automatic logic        reducedAbsFp16Reg_needShift_10;
        automatic logic [13:0] reducedAbsFp16Reg_nextExt_10;
        automatic logic [4:0]  reducedAbsFp16Reg_nextExp_10;
        automatic logic        reducedAbsFp16Reg_needShift_11;
        automatic logic [13:0] reducedAbsFp16Reg_nextExt_11;
        automatic logic [4:0]  reducedAbsFp16Reg_nextExp_11;
        automatic logic        reducedAbsFp16Reg_needShift_12;
        automatic logic [13:0] reducedAbsFp16Reg_nextExt_12;
        reducedAbsFp16Reg_lhsExpEff =
          (|(reducedAbsFp16Reg[14:10])) ? reducedAbsFp16Reg[14:10] : 5'h1;
        _reducedAbsFp16Reg_rhsAligned_T = reducedAbsFp16Reg_lhsExpEff + 5'hF;
        _reducedAbsFp16Reg_rawDiff_T =
