  );
endmodule

module AdderComparatorReduceNode(
  input         io_mode,
  input  [15:0] io_leftValue,
                io_rightValue,
  input  [3:0]  io_leftIndex,
                io_rightIndex,
  output [15:0] io_outValue,
  output [3:0]  io_outIndex
);

  wire [15:0] _adder_io_z;
  wire        leftIsLower =
    (io_leftValue[15]
       ? ~io_leftValue
       : io_leftValue
         ^ 16'h8000) < (io_rightValue[15] ? ~io_rightValue : io_rightValue ^ 16'h8000);
  Fp16AddWrapper adder (
    .io_a (io_mode ? 16'h0 : io_leftValue),
    .io_b (io_mode ? 16'h0 : io_rightValue),
    .io_z (_adder_io_z)
  );
  assign io_outValue =
    io_mode ? (leftIsLower ? io_leftValue : io_rightValue) : _adder_io_z;
  assign io_outIndex = io_mode ? (leftIsLower ? io_leftIndex : io_rightIndex) : 4'h0;
endmodule

