     {io_cmdReq_1_bits_mode},
     {io_cmdReq_0_bits_mode}};
  wire [3:0][1:0]  _GEN_2 =
    {{io_cmdReq_3_bits_srcSramId},
     {io_cmdReq_2_bits_srcSramId},
     {io_cmdReq_1_bits_srcSramId},
     {io_cmdReq_0_bits_srcSramId}};
  wire [3:0][10:0] _GEN_3 =
    {{io_cmdReq_3_bits_baseAddr},
     {io_cmdReq_2_bits_baseAddr},
     {io_cmdReq_1_bits_baseAddr},
     {io_cmdReq_0_bits_baseAddr}};
