     {io_cmdReq_2_bits_elemCount},
     {io_cmdReq_1_bits_elemCount},
     {io_cmdReq_0_bits_elemCount}};
  wire             grantCmd_mode = (|_grantValid_T) & _GEN_1[grantIdx];
