  reg              rspPendingReg;
  reg  [1:0]       rspSeqReg;
  reg  [11:0]      rspBitsReg_reqId;
  reg              rspBitsReg_mode;
  reg  [15:0]      rspBitsReg_resultValue;
  reg  [11:0]      rspBitsReg_resultIndex;
