        {io_cmdRsp_3_ready & isTargetRsp_3,
         io_cmdRsp_2_ready & isTargetRsp_2,
         io_cmdRsp_1_ready & isTargetRsp_1,
         io_cmdRsp_0_ready & isTargetRsp} == 4'h0 & (_GEN_5 | rspPendingReg);
