        activeValidReg = 1'h0;
        activeSeqReg = 2'h0;
        activeCmdReg_mode = 1'h0;
        activeCmdReg_reqId = 12'h0;
        rspPendingReg = 1'h0;
        rspSeqReg = 2'h0;
        rspBitsReg_reqId = 12'h0;
