  assign io_cmdReq_1_ready = launchFire & grantIdx == 2'h1;
  assign io_cmdReq_2_ready = launchFire & grantIdx == 2'h2;
  assign io_cmdReq_3_ready = launchFire & (&grantIdx);
  assign io_cmdRsp_0_valid = isTargetRsp;
  assign io_cmdRsp_0_bits_reqId = rspBitsReg_reqId;
  assign io_cmdRsp_0_bits_mode = rspBitsReg_mode;
