    end // always @(posedge)
  `endif // not def SYNTHESIS
  wire         gReqA = aSramIdReg == 2'h0 & _ctrl_io_aSram_enable;
  wire         gReqB = bSramIdReg == 2'h0 & _ctrl_io_bSram_enable;
  wire         gReqC = cSramIdReg == 2'h0 & _ctrl_io_cSram_enable;
  wire         lReqA = aSramIdReg == 2'h1 & _ctrl_io_aSram_enable;
  wire         lReqB = bSramIdReg == 2'h1 & _ctrl_io_bSram_enable;
  wire         lReqC = cSramIdReg == 2'h1 & _ctrl_io_cSram_enable;
