  SramWrapperSp #(
    .ADDR_WIDTH(8),
    .DATA_WIDTH(128),
    .DEPTH(224)
  ) mems_2 (
    .clock      (clock),
    .rw_enable  (io_enable & bankIdx == 2'h2),
    .rw_addr    (bankAddr),
    .rw_write   (io_write),
    .rw_dataIn  (io_dataIn),
    .rw_dataOut (_mems_2_rw_dataOut),
    .rw_bweb    (io_bweb)
